import json, sys
data = json.load(sys.stdin)
row = data['rows'][0]['row']
messages = row['messages']
# Get messages from 498 onwards
for i, msg in enumerate(messages):
    if i < 498:
        continue
    role = msg['role']
    content = msg.get('content', '')
    tool_uses = msg.get('tool_uses', None)
    thinking = msg.get('thinking', '')
    ts = msg.get('timestamp', '')

    print(f'\n=== Message {i} [{role}] @ {ts} ===')
    if content:
        print(f'Content: {content[:400]}')
    if thinking:
        print(f'Thinking: {thinking[:300]}')
    if tool_uses:
        for tu in tool_uses:
            print(f'Tool: {tu[\"tool\"]} | Input: {tu[\"input\"][:300]}')
